\u002b\u0032\u003d\u0049\u007a\u004e\u0044\u0023\u007b\u0056\u004d\u0046\u0068\u005b\u0021\u0023\u0025\u0042\u0054\u0067\u0070\u0051\u006d\u005e\u0034\u0024\u005d\u0033\u0020\u002a\u0052\u0042\u0061\u006f\u0063\u0074\u006c\u003a\u0071\u0057\u0067\u0035\u0043\u0022\u0074\u0055\u0055\u004e\u004b\u0032\u0043\u005a\u0074\u002b\u005c\u0048\u0062\u0020\u005a\u0067\u005b\u002f\u005f\u006e\u002d\u0040\u0077\u0036\u0045\u0032\u005c\u0061\u006c\u0078\u006c\u0021\u005c\u007b\u0049\u0028\u0032\u0032\u002a\u0031\u0079\u0020\u0030\u006d\u0030\u0051\u0051\u0048\u0071\u0030\u0054\u007b\u006c\u0063\u004e\u003f\u0076\u007a\u002a\u006b\u0068\u006e\u0058\u0031\u0035\u002c\u0041\u0031\u004e\u0072\u005c\u0042\u0065\u003a\u0059\u005a\u0064\u0048\u0053\u002d\u0066\u0033\u0045\u0077\u0065\u0040\u0068\u006f\u0032\u0028\u0066\u0025\u0022\u0069\u0040\u002c\u0026\u0049\u0076\u007a\u0026\u0050\u006d\u0056\u0033\u002e\u0047\u003f\u002a\u0025\u0060\u0025\u0068\u0038\u0063\u0071\u0026\u0051\u007c\u0023\u0049\u0050\u005a\u0057\u0043\u004b\u0071\u006b\u002f\u006b\u0037\u003d\u0079\u004e\u0051\u0059\u007c\u0048\u006c\u0062\u003f\u0059\u0041\u005e\u006b\u0050\u003c\u0033\u004b\u002a\u0067\u0045\u0038\u0038\u0064\u006e\u007c\u0055\u0063\u005d\u002c\u004b\u006b\u0027\u0053\u0029\u0062\u0032\u0078\u004a\u0070\u0047\u0053\u0056\u0032\u0072\u0027\u007c\u003f\u004f\u0054\u006f\u002b\u0047\u0058\u004f\u0030\u0075\u0051\u0055\u0042\u0077\u0058\u005e\u002d\u0033\u0052\u0062\u004c\u0072\u0040\u0023\u0064\u0072\u0041\u0046\u004e\u0031\u0074\u003c\u004f\u003f\u0040\u0076\u002d\u007e\u005f\u0031\u0065\u0070\u0070\u0058\u007d\u006a\u0032\u0027\u002f\u0078\u0067\u005a\u0077\u007a\u0048\u004e\u003e\u004b\u0050\u0048\u007b\u0042\u0020\u0077\u007b\u0040\u005f\u0076\u003a\u0024\u002e\u002a\u0045\u002e\u007b\u0046\u0073\u005f\u0043\u0022\u0078\u0063\u0044\u0073\u0052\u006a\u0032\u0069\u0044\u0037\u0030\u003d\u002e\u006d\u004f\u005d\u006e\u006b\u004e\u0032\u0045\u0073\u0041\u0069\u0027\u007a\u0021\u0068\u004a\u0024\u004b\u0028\u0054\u0027\u006f\u0060\u0074\u0031\u007e\u0030\u007c\u003c\u0075\u0022\u0024\u005a\u005b\u0043\u0053\u0020\u004b\u0061\u0025\u006e\u0066\u0020\u0027\u003d\u0058\u006c\u0060\u004d\u006a\u007c\u0051\u0043\u0043\u003a\u0030\u006f\u0045\u0050\u007e\u003d\u004e\u0036\u0070\u007a\u0031\u0027\u004c\u0047\u0078\u006c\u003f\u003e\u0037\u0058\u0038\u0076\u0021\u006d\u0060\u0029\u0037\u0079\u0039\u002c\u005d\u0031\u007d\u0039\u0078\u0032\u0046\u0060\u0054\u0052\u002e\u004a\u0075\u0041\u0070\u0031\u0030\u0048\u0033\u0038\u007b\u005a\u0026\u0029\u0045\u0044\u0065\u007b\u0047\u0024\u0057\u0022\u0066\u0028\u0070\u005c\u0056\u0049\u0068\u0071\u0045\u0075\u0045\u005e\u0077\u0064\u0052\u007d\u004b\u0071\u004d\u0067\u0029\u005d\u0058\u0043\u0075\u0025\u0039\u0032\u0025\u0076\u0030\u005d\u002a\u006f\u0075\u002f\u004e\u003b\u005b\u0050\u0039\u004a\u0073\u0020\u004d\u003c\u0021\u0049\u0042\u0026\u0066\u0029\u0030\u0061\u002d\u0040\u006d\u002f\u007a\u005a\u0052\u0067\u0063\u0038\u0050\u007c\u0045\u0059\u004f\u003c\u0022\u003a\u0050\u0029\u0025\u004e\u005c\u0036\u002d\u0045\u006e\u0051\u0042\u0064\u0023\u002d\u0079\u002a\u0034\u007c\u006b\u006e\u0062\u0021\u0023\u0038\u006e\u003c\u0054\u0028\u0028\u0027\u0077\u0037\u0023\u0033\u0059\u0047\u0033\u007c\u006c\u0032\u0074\u0076\u0029\u007e\u003c\u0028\u004a\u0078\u002a\u0020\u0053\u005d\u006b\u0049\u007c\u004b\u0049\u0031\u0045\u002d\u0039\u0021\u003f\u0067\u005c\u0055\u0078\u0055\u0070\u006c\u0039\u0050\u003f\u003c\u002b\u0034\u0067\u0047\u0079\u005e\u0029\u0056\u0063\u0076\u004a\u002a\u0020\u004c\u0026\u0052\u0045\u005b\u0021\u0066\u0064\u0042\u006d\u002e\u005a\u0062\u007e\u0047\u005f\u002a\u0071\u0041\u003d\u005b\u0038\u007e\u0061\u0058\u003c\u0062\u007e\u006a\u0028\u003c\u0065\u0035\u0041\u002e\u0072\u004b\u004f\u0024\u004c\u0071\u007e\u0020\u0072\u003f\u0027\u005d\u0066\u005b\u002e\u0067\u0032\u0033\u002c\u006c\u0043\u0067\u0045\u004c\u0026\u0050\u0064\u0068\u0023\u002c\u0033\u0020\u005c\u0027\u003f\u004c\u0032\u0021\u0079\u003e\u004b\u002e\u0034\u003f\u0050\u0062\u006b\u0040\u0029\u0079\u0044\u0047\u0060\u0076\u0064\u004e\u005b\u002b\u0048\u0057\u0059\u0052\u0043\u004a\u0055\u0070\u0062\u002f\u004a\u0041\u002a\u007b\u0027\u004b\u006f\u0054\u0052\u0079\u006f\u006f\u0068\u0063\u002c\u0060\u005d\u0026\u0061\u003e\u0031\u0029\u0028\u002b\u0033\u004d\u0046\u0046\u0020\u002c\u0023\u007e\u0054\u002d\u007e\u0050\u0041\u0042\u0034\u004e\u0062\u005a\u0078\u006c\u002c\u0067\u0035\u0047\u005f\u005b\u0049\u0068\u005b\u002f\u004d\u0052\u0026\u003d\u004f\u0028\u0040\u004d\u0025\u0020\u0057\u0045\u002a\u004d\u007c\u0032\u0023\u005e\u0060\u0041\u004c\u0077\u0035\u0043\u0036\u005a\u002f\u0041\u007e\u0030\u0059\u003e\u0043\u002c\u0048\u0078\u002a\u0074\u005b\u007c\u0030\u006b\u0053\u0060\u0048\u0038\u003b\u0023\u005e\u0038\u0025\u007c\u007d\u0032\u0035\u0075\u004e\u0039\u004b\u0064\u0074\u0076\u006f\u0057\u0034\u0073\u0031\u003e\u0076\u0078\u0057\u0058\u005d\u002d\u0067\u0044\u0026\u005f\u006e\u007b\u0039\u0043\u0038\u0069\u0079\u0026\u0046\u0039\u0020\u0021\u0043\u003c\u0021\u004b\u0025\u0057\u004b\u0053\u0056\u007c\u0021\u0053\u0046\u002c\u0060\u0033\u006f\u0055\u0072\u0025\u0027\u0066\u0029\u006c\u005c\u005a\u004e\u002a\u0072\u002c\u0053\u0035\u0050\u0071\u0079\u0046\u0079\u0066\u0020\u004a\u0033\u0047\u0068\u007b\u0063\u0037\u007d\u0021\u004a\u0049\u0030\u0059\u004a\u0066\u0036\u0025\u0073\u0028\u0031\u0074\u004d\u0065\u002e\u0064\u004b\u007c\u0026\u0041\u0077\u007b\u004f\u0037\u0070\u0027\u0068\u005a\u0075\u006f\u004f\u0062\u0069\u0059\u0043\u0062\u003c\u0023\u005f\u004a\u0069\u0060\u0043\u0075\u0025\u0020\u0075\u0031\u005c\u0044\u0072\u002d\u0064\u0072\u0069\u0069\u005f\u0048\u006c\u005c\u002e\u0022\u0044\u0060\u005c\u003e\u0039\u007e\u0073\u0064\u0031\u0020\u0057\u0029\u005f\u0068\u0052\u005f\u0055\u0039\u007e\u006d\u0030\u006c\u0046\u0047\u004f\u0074\u003a\u0025\u0051\u0053\u0078\u0031\u002d\u0031\u004c\u0068\u003e\u0031\u0044\u0060\u0066\u005f\u0063\u002a\u0075\u0029\u0040\u0039\u0039\u003d\u005d\u0046\u0028\u006f\u0049\u0051\u0044\u0043\u0075\u0040\u0037\u007a\u003f\u0049\u004d\u0025\u002e\u0036\u0050\u006e\u0065\u006c\u0049\u007c\u003d\u006b\u0060\u0070\u004d\u0039\u004b\u007d\u0065\u002e\u0075\u0043\u0071\u0031\u002b\u0061\u007a\u0051\u002a\u0067\u0037\u0024\u004e\u006d\u0033\u0053\u0066\u006d\u0042\u006d\u0045\u0059\u0074\u0025\u0047\u005d\u0032\u0045\u0029\u0039\u0038\u0040\u006d\u0032\u0048\u0031\u0040\u0051\u0078\u0022\u0060\u0029\u0065\u004a\u0071\u0037\u0040\u0058\u0040\u004a\u0055\u0035\u0063\u0062\u003f\u0042\u004d\u004d\u0039\u0060\u0044\u0030\u002b\u0041\u0034\u0069\u0058\u0020\u0032\u003f\u0031\u0041\u0027\u004c\u0034\u0058\u0074\u002c\u0076\u0047\u0039\u0066\u0024\u0028\u0060\u006d\u002b\u004d\u0023\u0077\u0053\u0041\u006d\u005e\u005f\u0035\u0046\u0026\u0038\u003d\u0045\u0042\u0056\u004a\u0053\u0041\u0029\u004a\u005d\u0050\u0069\u0023\u007a\u004e\u0051\u0073\u0031\u0057\u0069\u0030\u0058\u0027\u002d\u0070\u005d\u004a\u003c\u0058\u0035\u006e\u005d\u002e\u0076\u005d\u0021\u0073\u0023\u006a\u004f\u0053\u0025\u0022\u006c\u006e\u005b\u006b\u0052\u0056\u0073\u006c\u006f\u0041\u0046\u0050\u004b\u0051\u0057\u005e\u0061\u006a\u007d\u0020\u0028\u0034\u0070\u007e\u0044\u005d\u0048\u0020\u0079\u0054\u0038\u0061\u006f\u0044\u0032\u0040\u0063\u0037\u005a\u0030\u0054\u0037\u005c\u0073\u002d\u0036\u0072\u0023\u0043\u003f\u006b\u003a\u006a\u006c\u0045\u0023\u005b\u006d\u0035\u0067\u0064\u002c\u0048\u0049\u0053\u0023\u0027\u0041\u0059\u0064\u0049\u007e\u0063\u004a\u0074\u0035\u0036\u0060\u0027\u0020\u004a\u005f\u0069\u005b\u005a\u0064\u0050\u0035\u0067\u0051\u006b\u0022\u0065\u0048\u007e\u003a\u005b\u0072\u007d\u0074\u007b\u006e\u002c\u002e\u006e\u0076\u007a\u004c\u002b\u0066\u0079\u0037\u0031\u003a\u0029\u0039\u0065\u005e\u006e\u002d\u0050\u0049\u0068\u0078\u005a\u0056\u002f\u007d\u004a\u0027\u0033\u0061\u0068\u0065\u0034\u0071\u0023\u0078\u0044\u0034\u0048\u0079\u002b\u0057\u0074\u0070\u0060\u002e\u004f\u0058\u0046\u0079\u007c\u006e\u0022\u006d\u004c\u003d\u0060\u003e\u002e\u005b\u002a\u006d\u006a\u0069\u0030\u0032\u003f\u0066\u0078\u0057\u003c\u0023\u0067\u0062\u003b\u003c\u0038\u007c\u0071\u0042\u004c\u003a\u0027\u0073\u0028\u0024\u006a\u007d\u0072\u0040\u003d\u0026\u003a\u0049\u0033\u007a\u0059\u0028\u0029\u0020\u005c\u0053\u0055\u0045\u0072\u0065\u0047\u0031\u004c\u003a\u0063\u004a\u0067\u0050\u0022\u0047\u003a\u0039\u005b\u0046\u0077\u005e\u003b\u007d\u0043\u003c\u0060\u0030\u0071\u0074\u0041\u005d\u0036\u007a\u0042\u006f\u0027\u006f\u0024\u004d\u003a\u0040\u0040\u0021\u005e\u0058\u0074\u006f\u0060\u0064\u0031\u0050\u005b\u0051\u0039\u0070\u0070\u0025\u0053\u004c\u006b\u0069\u0067\u0073\u0053\u0039\u003f\u007e\u002e\u0070\u0041\u003d\u0064\u004d\u0023\u0046\u0070\u0032\u002f\u0045\u006b\u0024\u003f\u0071\u007b\u006b\u0023\u0072\u0069\u0027\u003a\u0051\u0058\u004e\u0058\u0039\u004e\u003d\u0025\u0052\u003c\u0057\u0043\u0021\u0055\u0042\u0071\u0073\u0054\u0024\u0047\u0047\u0023\u0064\u0054\u005e\u004f\u003d\u0033\u0023\u007d\u0060\u002d\u0041\u0058\u0027\u0035\u0056\u003c\u006e\u006c\u0032\u0046\u005c\u0069\u0055\u002f\u0035\u004a\u0071\u0028\u003f\u007b\u004d\u0061\u0079\u0072\u0041\u002b\u0079\u0026\u007e\u0035\u006e\u002f\u0048\u007d\u0060\u0055\u003a\u004a\u0064\u004e\u0056\u006d\u0052\u007d\u003a\u0058\u007c\u002a\u005c\u002b\u0056\u002e\u007d\u0046\u0062\u002b\u0054\u0026\u004e\u0059\u006e\u007c\u0052\u006f\u0052\u0035\u0046\u0060\u0039\u005d\u004e\u007c\u002f\u0025\u0042\u002d\u005b\u0059\u0076\u006a\u0064\u003a\u002e\u0076\u0076\u0054\u0078\u002d\u0070\u007e\u0037\u003e\u0079\u003d\u0068\u0021\u0062\u0027\u0049\u0053\u007c\u0036\u003b\u002e\u002f\u0041\u007d\u0039\u0032\u006c\u0032\u0051\u004a\u0070\u0029\u0066\u0053\u003d\u0036\u0034\u007b\u0043\u002e\u005f\u0046\u006f\u005e\u0050\u0056\u0072\u003c\u0069\u0060\u0021\u0042\u002d\u005c\u0031\u0036\u002e\u003d\u0075\u002f\u0049\u003e\u0025\u004d\u005b\u0020\u0033\u0022\u0031\u0058\u0028\u0056\u0072\u0025\u0043\u002c\u0037\u0079\u003e\u0025\u0065\u0079\u0075\u003c\u0050\u004d\u003f\u0072\u0049\u007e\u004d\u002e\u0029\u004a\u0067\u004b\u007e\u0031\u0066\u0066\u0046\u007b\u0054\u007c\u005c\u005d\u0071\u0029\u0056\u0049\u005b\u004b\u0055\u0024\u0058\u003e\u0033\u0051\u0056\u0069\u007b\u0033\u006b\u0042\u0061\u005c\u0065\u004f\u0067\u007e\u0030\u004e\u002a\u0050\u002f\u007d\u0052\u003e\u006b\u0065\u002f\u0054\u004b\u0033\u005f\u0064\u0023\u0041\u002f\u0024\u0020\u0064\u0032\u0075\u002c\u004f\u0020\u0041\u005d\u003c\u0031\u0048\u002e\u003c\u0068\u002b\u006d\u0068\u0041\u006a\u0065\u005d\u003a\u003a\u005a\u0049\u0061\u0033\u0064\u0075\u005d\u007e\u003c\u0059\u005c\u005d\u004f\u0073\u0043\u007d\u0073\u006c\u0037\u004a\u0078\u0071\u0047\u0023\u007d\u0025\u0028\u0041\u0078\u0060\u0048\u0051\u004c\u0069\u0053\u006d\u004a\u0051\u002f\u0049\u003b\u007b\u0079\u0067\u0078\u004f\u0070\u0057\u0055\u004f\u002a\u0067\u0066\u003e\u007e\u0044\u0063\u006a\u002b\u002b\u003e\u0058\u007d\u005b\u0062\u0046\u0055\u0026\u007e\u004c\u0029\u0067\u0059\u003f\u0057\u0032\u0077\u0020\u0042\u0031\u0034\u0064\u003e\u0051\u0022\u003c\u0046\u0047\u0022\u0069\u005d\u002d\u002c\u004b\u003f\u0065\u0043\u0022\u0073\u006a\u0031\u005d\u006d\u0060\u0026\u0039\u0057\u0045\u0031\u006f\u007c\u007e\u002b\u0067\u004f\u0058\u004d\u0038\u005d\u0022\u0059\u0061\u0056\u007e\u0070\u004b\u0020\u002e\u0071\u0030\u004a\u0079\u0077\u0079\u005d\u007e\u0052\u0061\u0035\u0024\u0047\u0071\u0069\u0033\u0050\u0057\u003f\u007d\u0060\u0046\u003f\u0064\u0031\u0050\u0078\u0071\u0067\u0041\u006b\u004f\u0037\u003d\u0045\u0059\u0068\u0031\u0071\u0072\u005a\u0052\u0051\u005b\u0024\u006e\u0021\u0061\u0076\u0064\u007c\u0033\u0066\u005e\u0069\u004a\u0067\u005a\u0065\u0062\u0030\u0051\u003d\u0061\u0062\u006b\u0022\u0071\u0071\u004f\u003a\u003f\u002d\u004e\u0052\u0076\u002f\u0053\u0030\u004c\u0069\u0049\u003a\u0045\u0067\u006c\u006a\u0060\u004a\u005e\u0078\u0062\u0032\u002e\u003c\u004f\u006b\u006c\u0065\u0041\u0071\u0036\u0042\u004f\u005b\u0057\u002e\u0043\u0040\u004c\u0071\u004e\u0061\u002c\u0043\u0059